PALETTE=[];MATERIAL_LOOKUP={};ORIGINAL={};PLACEMENT_RECORDS=[]
def decode_asset(id):
 raw=zlib.decompress(base64.b85decode(ENCODED[id]));assert len(raw)==LOCK[id]['bytes']and hashlib.sha256(raw).hexdigest()==LOCK[id]['sha256'];assert raw[:4]==b'glTF';offset=12;chunks={}
 while offset<len(raw):n,k=struct.unpack_from('<II',raw,offset);chunks[k]=raw[offset+8:offset+8+n];offset+=8+n
 d=json.loads(chunks[0x4e4f534a]);binary=chunks[0x004e4942];assert d['asset']['version']=='2.0'and not d.get('skins')and not d.get('animations')and not d.get('textures');mapping=[]
 for m in d['materials']:
  assert set(m)<={'name','doubleSided','pbrMetallicRoughness'}and m.get('doubleSided',False)is True;p=m['pbrMetallicRoughness'];assert set(p)<={'baseColorFactor','metallicFactor','roughnessFactor'}and len(p['baseColorFactor'])==4 and p['baseColorFactor'][3]==1
  value=(m['name'],tuple(p['baseColorFactor']),p.get('roughnessFactor',1),p.get('metallicFactor',1));key=json.dumps(value)
  if key not in MATERIAL_LOOKUP:MATERIAL_LOOKUP[key]=len(PALETTE);PALETTE.append(value)
  mapping.append(MATERIAL_LOOKUP[key])
 def accessor(i):
  a=d['accessors'][i];assert not a.get('sparse')and not a.get('normalized');v=d['bufferViews'][a['bufferView']];assert v.get('buffer',0)==0;fmt={5121:'B',5123:'H',5125:'I',5126:'f'}[a['componentType']];count={'SCALAR':1,'VEC2':2,'VEC3':3,'VEC4':4}[a['type']];size=struct.calcsize('<'+fmt*count);stride=v.get('byteStride',size);start=v.get('byteOffset',0)+a.get('byteOffset',0);assert start+(a['count']-1)*stride+size<=len(binary)
  return[struct.unpack_from('<'+fmt*count,binary,start+j*stride)for j in range(a['count'])]
 used=[];parts={}
 for node in d['nodes']:
  assert not any(k in node for k in['matrix','translation','rotation','scale']),('Nonidentity source requires an explicit different decoder',id,node.get('name'))
  if'mesh'not in node:continue
  mi=node['mesh'];used.append(mi);m=Mesh()
  for pr in d['meshes'][mi]['primitives']:
   assert pr.get('mode',4)==4;vv=accessor(pr['attributes']['POSITION']);ii=[x[0]for x in accessor(pr['indices'])];assert len(ii)%3==0
   for k in range(0,len(ii),3):m.tri([(vv[i][0],-vv[i][2],vv[i][1])for i in ii[k:k+3]],mapping[pr['material']])
  parts[node['name']]=dict(vertices=m.v,faces=m.f,face_materials=m.fm,material=m.fm[0],role='Complete retained source mesh, including every actual GLB triangle and per-face constant PBR.')
 assert sorted(used)==list(range(len(d['meshes']))),('All source meshes must be used once',id);return parts
for id in LOCK:ORIGINAL[id]=decode_asset(id)
placements=[('left_escarpment','nature-bank-escarpment-transition-01',(-1,0,.12)),('right_escarpment','nature-bank-escarpment-transition-01',(1,0,.12)),('upper_outcrop','nature-fractured-outcrop-01',(-.55,2.75,1.82)),('lower_scree','nature-companion-scree-01',(.6,-.5,.12)),('upper_grass','nature-dry-grass-clump-01',(1.45,2.5,1.82)),('lower_grass','nature-dry-grass-clump-01',(-1.2,-.6,.12))]
for instance,id,t in placements:
 source=ORIGINAL[id]
 for name,g in source.items():G[instance+'__'+name]=dict(g,vertices=[add(p,t)for p in g['vertices']],source_asset_id=id,instance_id=instance)
 PLACEMENT_RECORDS.append(dict(instance_id=instance,source_asset_id=id,translation_m=t,uniform_scale=1,source_meshes=len(source),source_triangles=sum(len(g['faces'])for g in source.values())))
# New low floor and height transition are scene-only support meshes, not new asset IDs.
soil=len(PALETTE);PALETTE.extend([('Scene_DrySoil',(.265,.240,.16,1),.94,0.),('Scene_EarthCut',(.18,.16,.105,1),.95,0.)])
def support_grid(xs,rows,name):
 m=Mesh();top=[[(x,y,z[i])for i,x in enumerate(xs)]for y,z in rows];bottom=[[(x,y,.12 if name=='RearPlateau'else 0.)for x in xs]for y,z in rows]
 for j in range(len(rows)-1):
  for i in range(len(xs)-1):m.quad(top[j][i],top[j][i+1],top[j+1][i+1],top[j+1][i],soil);m.quad(bottom[j][i+1],bottom[j][i],bottom[j+1][i],bottom[j+1][i+1],soil+1)
 for j in[0,len(rows)-1]:
  for i in range(len(xs)-1):m.quad(bottom[j][i],bottom[j][i+1],top[j][i+1],top[j][i],soil+1)
 for i in[0,len(xs)-1]:
  for j in range(len(rows)-1):m.quad(bottom[j][i],bottom[j+1][i],top[j+1][i],top[j][i],soil+1)
